<script setup lang="ts">
import {computed,ref} from 'vue'
import {apiFetch} from '../api'
const emit=defineEmits<{saving:[value:boolean]}>()
const busy=ref(false),error=ref(''),message=ref(''),preview=ref<any>(null),filename=ref(''),encoded=ref(''),downloaded=ref(false),confirmed=ref(false),issues=ref<any[]>([])
const totals=computed(()=>({added:(preview.value?.summary??[]).reduce((n:number,s:any)=>n+s.added,0),updated:(preview.value?.summary??[]).reduce((n:number,s:any)=>n+s.updated,0),retained:(preview.value?.summary??[]).reduce((n:number,s:any)=>n+s.retained,0)}))
const hasChanges=computed(()=>totals.value.added+totals.value.updated>0)
const display=(value:unknown)=>value===null?'Empty':String(value).slice(0,180)+(String(value).length>180?'…':'')
const name=(table:string)=>table.replace(/^school_/,'').replaceAll('_',' ')
async function response(r:Response){if(!r.ok){const body=await r.json().catch(()=>({}));issues.value=body.errors??[];if(r.status===409){downloaded.value=false;confirmed.value=false}throw Error(body.message??'Unable to transfer school data.')}return r}
async function run(action:()=>Promise<void>){busy.value=true;emit('saving',true);error.value='';message.value='';issues.value=[];try{await action()}catch(e){error.value=e instanceof Error?e.message:'Unable to transfer data.'}finally{busy.value=false;emit('saving',false)}}
async function saveDownload(r:Response,file:string){const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function download(){await run(async()=>{await saveDownload(await response(await apiFetch('/api/admin/school/transfer/export')),'studenthub-school-data.zip');message.value='School recovery package downloaded. Keep it in a private location.'})}
async function check(){if(!encoded.value)return;preview.value=null;downloaded.value=false;confirmed.value=false;await run(async()=>{const r=await response(await apiFetch('/api/admin/school/transfer/preview',{method:'POST',headers:{'Content-Type':'application/json','X-StudentHub':'1'},body:JSON.stringify({package:encoded.value})}));preview.value=await r.json()})}
async function upload(event:Event){preview.value=null;downloaded.value=false;confirmed.value=false;error.value='';issues.value=[];encoded.value='';const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';filename.value=file?.name??'';if(!file)return;if(file.size>6000000){error.value='Choose a ZIP file smaller than 6 MB.';return}try{const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));encoded.value=btoa(text);await check()}catch{error.value='Unable to read this file. Choose it again.'}}
async function recovery(){if(!preview.value)return;await run(async()=>{await saveDownload(await response(await apiFetch('/api/admin/school/transfer/recovery/'+preview.value.token)),'studenthub-before-import.zip');downloaded.value=true;message.value='Before-import package downloaded. Confirm you saved the file before continuing.'})}
async function apply(){if(!preview.value||!confirmed.value||!downloaded.value)return;await run(async()=>{const r=await response(await apiFetch('/api/admin/school/transfer/apply',{method:'POST',headers:{'Content-Type':'application/json','X-StudentHub':'1'},body:JSON.stringify({token:preview.value.token,recovery_downloaded:true})}));message.value=(await r.json()).message;preview.value=null;filename.value='';encoded.value='';downloaded.value=false;confirmed.value=false})}
</script>
<template><section class="transfer" :aria-busy="busy"><h2>School data &amp; recovery</h2><p>Save school records, inspect changes and recover previous values from a saved package.</p><p v-if="error" class="error" role="alert">{{error}}</p><section v-if="issues.length" class="issue-list" aria-label="Import validation errors"><h3>Fix these file errors</h3><ul><li v-for="(issue,i) in issues" :key="i"><strong>{{issue.file}}{{issue.row?' — row '+issue.row:''}}{{issue.field?', '+issue.field:''}}</strong><span>{{issue.message}}</span></li></ul><p>Showing up to 20 errors. Fix them, then preview again.</p></section><p v-if="message" class="success" role="status">{{message}}</p>
<div class="cards"><article><h3>1. Save your school data</h3><p>Includes school setup, people, classes, subjects, rooms, floors, timetables, bookings, canteen menus, homework, homework progress, attendance and notices.</p><button :disabled="busy" @click="download">Download recovery package</button><p class="muted">Contains private contact and academic information. Store it securely.</p></article><article><h3>2. Choose a saved package</h3><p>Upload a previous export to recover values, or a package with edited CSVs. Keep headers and referenced records.</p><label>Choose ZIP package<input type="file" accept=".zip,application/zip" :disabled="busy" @change="upload"></label><button v-if="encoded" type="button" class="secondary" :disabled="busy" @click="check">Preview again</button><p class="muted">6 MB compressed, 20 MB expanded, up to 20,000 records. Preview lasts 10 minutes.</p></article></div>
<p class="notice">Add and update only: unlisted records are kept. Recovering an older package does not delete records created afterward. Existing passwords and login access stay unchanged. New logins start disabled; provision them in Accounts.</p><details class="coverage"><summary>What this package does not recover</summary><p>Administrator and parent accounts, verified parent-child links, passwords, sessions, QR references, password requests, audit history and job favourites are excluded. Use a private full database backup to preserve the entire system. Recovered school notices are attributed to the importing administrator.</p></details>
<section v-if="preview" class="preview"><h3>3. Review {{filename}}</h3><p>{{preview.message}}</p><p class="muted">School: {{preview.package_info.school_name}}. Exported: {{preview.package_info.exported_at||'Not recorded'}}. {{preview.package_info.same_installation?'From this installation.':'From another installation; records are matched by their school identifiers.'}}</p><div class="preview-totals"><span><strong>{{totals.added}}</strong> new</span><span><strong>{{totals.updated}}</strong> updates</span><span><strong>{{totals.retained}}</strong> unlisted records kept</span></div><div class="table-scroll" tabindex="0" aria-label="Import summary"><table><thead><tr><th scope="col">Records</th><th scope="col">New</th><th scope="col">Updates</th><th scope="col">Unchanged</th><th scope="col">Unlisted kept</th></tr></thead><tbody><tr v-for="s in preview.summary" :key="s.table"><th scope="row">{{name(s.table)}}</th><td>{{s.added}}</td><td>{{s.updated}}</td><td>{{s.unchanged}}</td><td>{{s.retained}}</td></tr></tbody></table></div><details v-if="preview.changes.length" class="change-details"><summary>See before and after values ({{preview.changes.length}}{{preview.changes_truncated?' shown':''}})</summary><p v-if="preview.changes_truncated">Showing the first 100 changed records. The table above includes the full counts.</p><article v-for="(change,i) in preview.changes" :key="i" class="change-record"><h4>{{change.action==='add'?'New record':'Update'}} — {{change.file}}, row {{change.row}}</h4><dl><template v-for="field in change.fields" :key="field.field"><dt>{{field.field.replaceAll('_',' ')}}</dt><dd><span v-if="change.action==='update'" class="old-value">Before: {{display(field.before)}}</span><span>After: {{display(field.after)}}</span></dd></template></dl></article></details>
<template v-if="hasChanges"><h3>4. Save a recovery copy, then import</h3><p>Download the current records before applying changes. You can upload that package later to recover earlier values while keeping any new records.</p><button type="button" class="secondary" :disabled="busy" @click="recovery">{{downloaded?'Download recovery copy again':'Download before-import copy'}}</button><label class="confirmation"><input v-model="confirmed" type="checkbox" :disabled="busy||!downloaded">I saved the recovery copy and reviewed these changes.</label><div class="actions"><button :disabled="busy||!downloaded||!confirmed" @click="apply">{{busy?'Working…':'Apply reviewed changes'}}</button><button class="secondary" :disabled="busy" @click="preview=null">Cancel preview</button></div></template><p v-else class="success">This package matches the current records. Nothing needs to be imported.</p></section><p v-if="busy" role="status">Processing school records…</p></section></template>
<style scoped>
.transfer{background:#fff;border:1px solid #dbe5df;border-radius:16px;padding:24px;color:#294638;min-width:0}.transfer h2{margin:6px 0 12px}.transfer p,.transfer li{font-size:13px;line-height:1.6}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.cards article,.preview{padding:18px;border:1px solid #dbe5df;border-radius:12px;margin:14px 0;min-width:0}.cards h3{margin-top:0;font-size:17px}.muted{color:#697c71}.notice,.success,.error{padding:12px;border-radius:8px}.notice,.success{background:#edf5ef}.error,.issue-list{background:#faeeeb;color:#a13c2c}.issue-list{padding:14px;border-radius:8px}.issue-list ul{padding-left:20px}.issue-list li{margin:10px 0}.issue-list span{display:block}button{width:auto;margin:8px 0;border:0;border-radius:8px;background:#38624f;color:white;padding:10px 14px;min-height:44px;font:inherit;font-size:14px;cursor:pointer}button:disabled{opacity:.55}input{display:block;max-width:100%;margin-top:8px}label{font-weight:600;font-size:13px}.table-scroll{overflow:auto;max-height:360px;border:1px solid #dbe5df;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e1e9e4}thead th{background:#f1f6f3;position:sticky;top:0}.actions,.preview-totals{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.preview-totals{margin-bottom:16px}.preview-totals span{padding:10px 12px;border-radius:8px;background:#edf5ef;font-size:13px}.secondary{background:#e8efea;color:#38624f}.transfer summary{min-height:44px;display:list-item;cursor:pointer;font-size:14px;font-weight:600;padding:12px 0}.change-record{border-top:1px solid #dbe5df;padding:12px 0}.change-record h4{margin:0 0 10px;font-size:13px}.change-record dl{display:grid;grid-template-columns:minmax(80px,1fr) 3fr;gap:8px;font-size:13px}.change-record dt{font-weight:600}.change-record dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.change-record dd span{display:block}.old-value{color:#697c71}.confirmation{display:flex;align-items:start;gap:10px;margin:16px 0;font-size:13px;line-height:1.5}.confirmation input{width:20px;height:20px;min-width:20px;margin:0}.transfer :is(button,input,summary,.table-scroll):focus-visible{outline:2px solid #21896f;outline-offset:2px}@media(max-width:650px){.cards{grid-template-columns:1fr;gap:0}.transfer{padding:16px}.preview{padding:12px}.change-record dl{grid-template-columns:1fr;gap:4px}.change-record dd{margin-bottom:10px}}
</style>
